//! The end-to-end output: a golden fixture (`tests/fixtures/e2e/expected`, rewritten by
//! `SPECC_BLESS=1`), a syntax check of every generated file with `node --check`, and the
//! refusals. Then the two committed outputs: Strata's own journeys (`tests/e2e/generated`) and the
//! step fixtures (`tests/e2e/step-checks`, from `tests/e2e/step-fixtures/spec.jsonc`), which hold a
//! journey that passes and one that must fail for every step kind; Playwright runs those against
//! the fixture pages of `tests/e2e/step-fixtures/server.mjs`.

use std::fs;
use std::path::PathBuf;
use std::process::Command;

use strata_spec_compiler::e2e;
use strata_spec_compiler::{output, GeneratedFile};

const FIXTURE_SPEC: &str = "crates/spec-compiler/tests/fixtures/e2e/spec.jsonc";

fn manifest_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn fixture_text() -> String {
    fs::read_to_string(manifest_dir().join("tests/fixtures/e2e/spec.jsonc")).unwrap()
}

fn fixture_files() -> Vec<GeneratedFile> {
    e2e::generate(FIXTURE_SPEC, &fixture_text()).unwrap().files
}

fn contents<'a>(files: &'a [GeneratedFile], path: &str) -> &'a str {
    &files
        .iter()
        .find(|f| f.path == path)
        .unwrap_or_else(|| panic!("no file {path}"))
        .contents
}

/// The codes the specification is refused with, after `edit` changed its text.
fn refusal(edit: impl Fn(&str) -> String) -> Vec<String> {
    e2e::generate(FIXTURE_SPEC, &edit(&fixture_text()))
        .unwrap_err()
        .into_iter()
        .map(|d| d.code)
        .collect()
}

#[test]
fn golden_output_matches_the_expected_files() {
    let dir = manifest_dir().join("tests/fixtures/e2e/expected");
    let files = fixture_files();
    if std::env::var("SPECC_BLESS").as_deref() == Ok("1") {
        output::write(&dir, &files).unwrap();
        return;
    }
    let differences = output::compare(&dir, &files).unwrap();
    assert!(
        differences.is_empty(),
        "tests/fixtures/e2e/expected is not what specc e2e generates: {differences:?}. \
         Run the test with SPECC_BLESS=1 to rewrite it, and review the change."
    );
}

#[test]
fn every_file_has_the_header_and_generation_is_repeatable() {
    let files = fixture_files();
    assert_eq!(files, fixture_files());
    let paths: Vec<&str> = files.iter().map(|f| f.path.as_str()).collect();
    assert_eq!(
        paths,
        [
            "journey.js",
            "playwright.generated.config.js",
            "read-an-essay.spec.js",
            "readers-see-it-live.spec.js",
            "sign-in-offline.spec.js",
        ]
    );
    for file in &files {
        assert!(
            file.contents.starts_with(
                "// @generated by specc from crates/spec-compiler/tests/fixtures/e2e/spec.jsonc."
            ),
            "{} has no header",
            file.path
        );
    }
}

#[test]
fn verifies_comments_sit_directly_above_the_test_call() {
    let files = fixture_files();
    let text = contents(&files, "read-an-essay.spec.js");
    assert!(text.contains(
        "// Verifies: R-10\n// Verifies: R-12\ntest(\"a reader opens an essay from the front page\""
    ));
    let none = contents(&files, "sign-in-offline.spec.js");
    assert!(!none.contains("Verifies"));
}

#[test]
fn generated_files_are_valid_javascript() {
    let probe = Command::new("node").arg("--version").output();
    if probe.map(|o| !o.status.success()).unwrap_or(true) {
        eprintln!("node is not installed; skipping");
        return;
    }
    let dir = std::env::temp_dir().join(format!("specc-e2e-check-{}", std::process::id()));
    output::write(&dir, &fixture_files()).unwrap();
    for file in fixture_files() {
        // The files are ES modules (import syntax, import.meta), so check them as such.
        let copy = dir.join(file.path.replace(".js", ".mjs"));
        fs::copy(dir.join(&file.path), &copy).unwrap();
        let check = Command::new("node")
            .arg("--check")
            .arg(&copy)
            .output()
            .unwrap();
        assert!(
            check.status.success(),
            "node --check {} failed: {}",
            file.path,
            String::from_utf8_lossy(&check.stderr)
        );
    }
    let _ = fs::remove_dir_all(&dir);
}

#[test]
fn a_specification_without_journeys_is_refused() {
    let err = e2e::generate("s.jsonc", "{}").unwrap_err();
    assert_eq!(err[0].code, e2e::NO_SCENARIOS);
    let err = e2e::generate("s.jsonc", "{ not json").unwrap_err();
    assert_eq!(err[0].code, e2e::SYNTAX);
}

#[test]
fn a_wait_for_with_no_live_binding_is_refused() {
    let codes = refusal(|t| t.replace("\"liveBindings\": [", "\"liveBindingsOff\": ["));
    assert_eq!(codes, [e2e::WAIT_UNOBSERVABLE]);
}

#[test]
fn a_status_before_any_navigation_is_refused() {
    let codes = refusal(|t| {
        t.replace(
            "{ \"goto\": { \"screen\": \"post\", \"params\": { \"slug\": \"on-sharpening\" } } },\n        { \"expectStatus\": 200 },",
            "{ \"expectStatus\": 200 },",
        )
    });
    assert_eq!(codes, [e2e::STATUS_WITHOUT_GOTO]);
}

#[test]
fn a_selector_or_a_missing_label_is_refused() {
    let codes = refusal(|t| t.replace("{ \"axeScan\": {} }", "{ \"click\": \"#save\" }"));
    assert_eq!(codes, [e2e::STEP]);
    let codes = refusal(|t| t.replace("\"label\": \"Name\", ", ""));
    assert_eq!(codes, [e2e::FIELD_LABEL]);
    let codes = refusal(|t| t.replace("\"submitLabel\": \"Sign in\"", "\"x\": 1"));
    assert_eq!(codes, [e2e::SUBMIT_LABEL]);
}

#[test]
fn a_requirement_without_a_ref_is_refused() {
    let codes = refusal(|t| t.replace("\"ref\": \"R-10\", ", ""));
    assert_eq!(codes, [e2e::VERIFIES]);
}

#[test]
fn an_expect_log_becomes_a_poll_of_the_service_log() {
    let files = fixture_files();
    let text = contents(&files, "sign-in-offline.spec.js");
    assert!(text.contains("{ logs: true }"));
    assert!(text.contains(
        "await j.expectLog(\"backend\", \"record.updated\", { level: \"info\", fields: {\"tenant\":\"fieldnotes\",\"transition\":\"publish\"}, members: [\"tenant\",\"object\",\"transition\"], timeout: 8000 });"
    ));
    assert!(contents(&files, "journey.js")
        .contains("const LOG_FILES = {\"backend\":\"var/logs/backend.jsonl\"};"));
    assert!(!contents(&files, "read-an-essay.spec.js").contains("expectLog"));
    assert!(contents(&files, "read-an-essay.spec.js").contains("{ logs: true }"));
}

#[test]
fn an_expect_log_of_an_event_that_is_not_logged_is_refused() {
    let codes = refusal(|t| {
        t.replace(
            "\"event\": \"record-updated\", \"fields\": { \"object\"",
            "\"event\": \"page-pinged\", \"fields\": { \"object\"",
        )
    });
    assert_eq!(codes, [e2e::LOG_EVENT]);
}

#[test]
fn an_expect_log_in_the_log_of_another_service_is_refused() {
    let codes = refusal(|t| {
        t.replace("{ \"expectLog\": { \"service\": \"backend\", \"event\": \"record-updated\", \"fields\": { \"object\"", "{ \"expectLog\": { \"service\": \"bff\", \"event\": \"record-updated\", \"fields\": { \"object\"")
    });
    assert_eq!(codes, [e2e::LOG_EVENT]);
}

#[test]
fn an_expect_log_of_a_member_the_line_does_not_hold_is_refused() {
    let codes = refusal(|t| {
        t.replace(
            "\"fields\": { \"object\": \"post\" }",
            "\"fields\": { \"body\": \"post\" }",
        )
    });
    assert_eq!(codes, [e2e::LOG_EVENT]);
}

fn repo_root() -> PathBuf {
    manifest_dir().join("../..")
}

/// The files `specc e2e` writes from a specification of the repository, with its options.
fn generated(spec: &str, options: &e2e::Options) -> Vec<GeneratedFile> {
    let text = fs::read_to_string(repo_root().join(spec)).unwrap();
    e2e::generate_with(spec, &text, options)
        .unwrap_or_else(|d| panic!("specc e2e refuses {spec}: {d:#?}"))
        .files
}

fn strata_options() -> e2e::Options {
    e2e::Options {
        origin: Some("http://127.0.0.1:4200".into()),
        expect_fail_prefix: None,
    }
}

fn step_options() -> e2e::Options {
    e2e::Options {
        origin: None,
        expect_fail_prefix: Some("violates-".into()),
    }
}

const STEP_SPEC: &str = "tests/e2e/step-fixtures/spec.jsonc";

/// The journeys of the Strata specification, generated once for every test in this binary.
fn strata_files() -> &'static Vec<GeneratedFile> {
    static FILES: std::sync::OnceLock<Vec<GeneratedFile>> = std::sync::OnceLock::new();
    FILES.get_or_init(|| generated("specifications/spec.jsonc", &strata_options()))
}

#[test]
fn strata_journeys_generate_and_are_committed() {
    let files = strata_files();
    let differences = output::compare(&repo_root().join("tests/e2e/generated"), files).unwrap();
    assert!(
        differences.is_empty(),
        "tests/e2e/generated is not what specc e2e generates: {differences:?}; run npm run generate"
    );
}

#[test]
fn the_full_journey_checks_the_backend_log_after_each_step() {
    let files = strata_files();
    let text = contents(files, "ui-author-writes-publishes-live.spec.js");
    let events: Vec<&str> = text
        .lines()
        .filter_map(|l| l.trim().strip_prefix("await j.expectLog(\"backend\", \""))
        .map(|rest| rest.split('"').next().unwrap())
        .collect();
    assert_eq!(
        events,
        [
            "session.started",
            "record.created",
            "record.updated",
            "record.updated",
            "record.deleted",
            "session.ended"
        ]
    );
    assert!(text.contains("\"transition\":\"publish\""));
    assert!(text.contains("\"transition\":\"unpublish\""));
    assert!(text.contains("await j.waitFor(["));
    assert!(text.contains(
        "await j.logScan([j.re(\"${authorSession}\"), j.re(\"${authorCsrf}\"), j.re(\"strata-dev-\")]);"
    ));
    // The runtime links each line to a request the journey's browsers sent and to the BFF's line.
    let runtime = contents(files, "journey.js");
    assert!(runtime.contains("this.correlations.has(line.correlation)"));
    assert!(
        runtime.contains("l.json.service !== service && l.json.correlation === line.correlation")
    );
    assert!(runtime.contains("spawnSync('podman', ['logs', name]"));
    assert!(runtime.contains("const WRITTEN_ORIGIN = \"http://127.0.0.1:4200\";"));
}

#[test]
fn the_security_journeys_expect_what_the_backend_now_answers() {
    let files = strata_files();
    let others = contents(files, "ui-author-cannot-edit-others.spec.js");
    assert!(others.contains("\"id\":15"));
    assert!(others.contains("\"expectJson\":{\"code\":\"not_found\"},\"expectStatus\":404"));
    assert!(others.contains(
        "\"expectJson\":{\"failed.0.rule\":\"policy:authors_own_posts\"},\"expectStatus\":403"
    ));
    let ends = contents(files, "ui-session-ends.spec.js");
    assert!(ends.contains("fill(\"admin\")"));
    assert!(!ends.contains("tomasz"));
}

#[test]
fn step_fixtures_are_committed() {
    let files = generated(STEP_SPEC, &step_options());
    let differences = output::compare(&repo_root().join("tests/e2e/step-checks"), &files).unwrap();
    assert!(
        differences.is_empty(),
        "tests/e2e/step-checks is not what specc e2e generates: {differences:?}; run npm run generate"
    );
}

/// Every step kind has a fixture journey that passes and one that must fail, and the step a
/// failing journey ends with is the kind it is named for (or, for a step that asserts nothing,
/// the assertion that shows its effect).
#[test]
fn every_step_kind_has_a_passing_and_a_failing_fixture() {
    let text = fs::read_to_string(repo_root().join(STEP_SPEC)).unwrap();
    let plan = e2e::load(&text).unwrap();
    for (kind, _) in e2e::STEP_KINDS {
        let uses = |prefix: &str| {
            plan.scenarios.iter().any(|s| {
                s.id.starts_with(prefix)
                    && s.steps
                        .iter()
                        .any(|st| st.as_object().is_some_and(|o| o.contains_key(*kind)))
            })
        };
        assert!(uses("pass-"), "no passing fixture uses {kind}");
        assert!(uses("violates-"), "no failing fixture uses {kind}");
    }
    let files = generated(STEP_SPEC, &step_options());
    for s in &plan.scenarios {
        let body = contents(&files, &format!("{}.spec.js", s.id));
        assert_eq!(
            body.contains("test.fail();"),
            s.id.starts_with("violates-"),
            "{}",
            s.id
        );
    }
}
